import { describe, it, expect } from 'vitest';
import { FeatureStudioGenerator, NodeFeaturescriptInfo } from '../featurestudiogenerator';

const HEADER = [
    '// Generated by Onshape Node Editor',
    '// Edits will be overwritten by the Onshape Node Editor app',
    'FeatureScript 2960;',
].join('\n');

describe('FeatureStudioGenerator', () => {
    it('writes the generated header, the language version and a default import', () => {
        const code = new FeatureStudioGenerator().generateFeatureStudioCode([{ line: 'f();' }]);

        expect(code).toBe(
            `${HEADER}\n` +
            'import(path : "onshape/std/common.fs", version : "2960.0");\n' +
            '\n' +
            'f();\n',
        );
    });

    it('honours an explicit FeatureScript version', () => {
        const code = new FeatureStudioGenerator('2770').generateFeatureStudioCode([]);

        expect(code).toContain('FeatureScript 2770;');
        expect(code).toContain('import(path : "onshape/std/common.fs", version : "2770.0");');
    });

    it('dedupes dependencies by path and sorts the imports', () => {
        const info: NodeFeaturescriptInfo[] = [
            {
                line: 'one();',
                dependencies: [
                    { path: 'onshape/std/units.fs', version: '2770.0' },
                    { path: 'onshape/std/feature.fs', version: '2770.0' },
                ],
            },
            {
                line: 'two();',
                // duplicate path: the last declaration wins, exactly once
                dependencies: [{ path: 'onshape/std/units.fs', version: '9999.0' }],
            },
        ];

        const imports = new FeatureStudioGenerator()
            .generateFeatureStudioCode(info)
            .split('\n')
            .filter((line) => line.startsWith('import('));

        expect(imports).toEqual([
            'import(path : "onshape/std/feature.fs", version : "2770.0");',
            'import(path : "onshape/std/units.fs", version : "9999.0");',
        ]);
    });

    it('does not add the default import when dependencies are declared', () => {
        const code = new FeatureStudioGenerator().generateFeatureStudioCode([
            { line: 'f();', dependencies: [{ path: 'onshape/std/feature.fs', version: '2770.0' }] },
        ]);

        expect(code).not.toContain('onshape/std/common.fs');
    });

    it('indents a block opened by postindent and closes it with a negative preindent', () => {
        const info: NodeFeaturescriptInfo[] = [
            { line: 'annotation {}', postindent: 1 },
            { line: 'open()' },
            { line: 'body();' },
            { line: 'close();', preindent: -1 },
        ];

        const lines = new FeatureStudioGenerator()
            .generateFeatureStudioCode(info)
            .split('\n')
            .slice(5); // past header (3 lines) + default import + blank line

        expect(lines).toEqual(['annotation {}', '\topen()', '\tbody();', 'close();', '']);
    });

    it('indents every line of a multi-line item', () => {
        const info: NodeFeaturescriptInfo[] = [
            { line: 'outer', postindent: 1 },
            { line: 'a();\nb();' },
        ];

        const lines = new FeatureStudioGenerator()
            .generateFeatureStudioCode(info)
            .split('\n')
            .slice(5);

        expect(lines).toEqual(['outer', '\ta();', '\tb();', '']);
    });

    it('clamps a negative indent at column zero', () => {
        const info: NodeFeaturescriptInfo[] = [{ line: '});', preindent: -2 }];

        const lines = new FeatureStudioGenerator()
            .generateFeatureStudioCode(info)
            .split('\n')
            .slice(5);

        expect(lines).toEqual(['});', '']);
    });
});
